+/**
+ * Variance per item between two days (inclusive): theoretical use from the
+ * sales sold in those days, actual use from every "consume" movement, and
+ * the difference (actual - theoretical). Items where both are 0 are left out.
+ */
+export function varianceReport(store, from, to) {
+  const round = (n) => Math.round(n * 1000) / 1000;
+  const theoretical = new Map();
+  for (const sale of listSales(store)) {
+    const day = dayOf(sale.soldAt);
+    if (day < from || day > to) continue;
+    for (const n of saleUse(store, sale)) theoretical.set(n.itemId, round((theoretical.get(n.itemId) ?? 0) + n.qty));
+  }
+  const actual = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || m.qty <= 0) continue;
+    const day = dayOf(m.at);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (!batch) continue;
+    actual.set(batch.itemId, round((actual.get(batch.itemId) ?? 0) + m.qty));
+  }
+  return listItems(store)
+    .map((item) => {
+      const t = theoretical.get(item.id) ?? 0;
+      const a = actual.get(item.id) ?? 0;
+      return { itemId: item.id, name: item.name, unit: item.unit, theoretical: t, actual: a, difference: round(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
