+// Sales from the till. Each sold dish uses one portion of its recipe per
+// `qty`; the ingredients are consumed with the ledger ref `sale:<ticket>`.
+import { consume } from "./batches.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+/** Every recorded sale line, in id order. */
+export function listSales(store) {
+  return [...(store.data.sales ?? [])].sort((a, b) => a.id - b.id);
+}
+
+/** True when a ticket has already been recorded. */
+export function ticketRecorded(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/** Ingredient quantities one sale line uses, per item (3 decimals). */
+export function saleUse(store, sale) {
+  return scaled(getRecipe(store, getDish(store, sale.dishId).recipeId), sale.qty);
+}
+
+/** Records one sale line and consumes its ingredients; throws not_enough_stock. */
+export function recordSale(store, { ticket, soldAt, dishId, qty }) {
+  const sale = { ticket, soldAt, dishId, qty };
+  for (const n of saleUse(store, sale))
+    if (n.qty > 0) consume(store, n.itemId, n.qty, { at: soldAt, ref: `sale:${ticket}` });
+  store.data.sales ??= [];
+  const saved = { id: store.nextId("sale"), ...sale };
+  store.data.sales.push(saved);
+  return saved;
+}
